import { Suspense } from 'react'
import { Button } from "@/components/ui/button"
import { DocumentsTable } from "@/app/vault/DocumentsTable"
import { Skeleton } from "@/components/ui/skeleton"

export default function VaultPage() {
    return (
        <div className="flex flex-1 flex-col gap-4 p-4 pt-0">
            <div className="flex items-center justify-between space-y-2">
                <h2 className="text-3xl font-bold tracking-tight">Vault</h2>
                <div className="flex items-center space-x-2">
                    <Button>Upload</Button>
                </div>
            </div>
            {/* 
         Removed the manual Search input here because the DataTable 
         component now includes its own filter input (or we can move it up later).
         For now, keeping the page structure clean.
      */}

            <Suspense fallback={<TableSkeleton />}>
                <DocumentsTable />
            </Suspense>
        </div>
    )
}

function TableSkeleton() {
    return (
        <div className="w-full space-y-4">
            <div className="flex items-center justify-between">
                <Skeleton className="h-10 w-[250px]" />
                <Skeleton className="h-10 w-[100px]" />
            </div>
            <div className="rounded-md border">
                <div className="h-[400px] w-full p-4 space-y-4">
                    <div className="space-y-2">
                        <Skeleton className="h-8 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                    </div>
                </div>
            </div>
            <div className="flex items-center justify-end space-x-2">
                <Skeleton className="h-8 w-[100px]" />
                <Skeleton className="h-8 w-[80px]" />
                <Skeleton className="h-8 w-[80px]" />
            </div>
        </div>
    )
}
